func TestAnalyzeFunctionDeclaration(t *testing.T) {
	src := `fn add(x, y) { return x + y }`
	module := parseTestCode(t, src)

	analyzer := NewAnalyzer()
	err := analyzer.Analyze(module)
	if err != nil {
