	jumpCount := 0
	for _, ins := range program.Instructions {
		if ins.Opcode == OpJumpIfFalse || ins.Opcode == OpJump {
			jumpCount++
		}
	}

	if jumpCount < 2 {
		t.Errorf("expected at least 2 jump instructions, got %d", jumpCount)
	}
}

