		right := vm.pop()
		left := vm.pop()
		vm.push(vm.add(left, right))

	case compiler.OpSub:
		right := vm.pop()
		left := vm.pop()
		vm.push(vm.subtract(left, right))

	case compiler.OpMul:
		right := vm.pop()
		left := vm.pop()
		vm.push(vm.multiply(left, right))

	case compiler.OpDiv:
		right := vm.pop()
		left := vm.pop()
		vm.push(vm.divide(left, right))

	case compiler.OpMod:
		right := vm.pop()
		left := vm.pop()
		vm.push(vm.modulo(left, right))

	case compiler.OpEqual:
		right := vm.pop()
		left := vm.pop()
		vm.push(vm.equal(left, right))

	case compiler.OpNotEqual:
		right := vm.pop()
		left := vm.pop()
		vm.push(!vm.equal(left, right).(bool))

	case compiler.OpLess:
		right := vm.pop()
		left := vm.pop()
		vm.push(vm.less(left, right))

	case compiler.OpGreater:
		right := vm.pop()
		left := vm.pop()
		vm.push(vm.greater(left, right))

	case compiler.OpAnd:
		right := vm.pop()
		left := vm.pop()
		vm.push(vm.isTruthy(left) && vm.isTruthy(right))

	case compiler.OpOr:
		right := vm.pop()
		left := vm.pop()
		vm.push(vm.isTruthy(left) || vm.isTruthy(right))

	case compiler.OpNot:
		val := vm.pop()
		vm.push(!vm.isTruthy(val))

