				args[i] = vm.pop()
			}

			// Call function
			if builtin, ok := vm.builtins[fnName]; ok {
				result, err := builtin(args...)
				if err != nil {
					return pc + 1, err
				}
				vm.push(result)
			}
		}

	case compiler.OpArrayCreate:
		if len(ins.Args) > 0 {
			count := ins.Args[0].(int)
			arr := make([]interface{}, count)
			for i := count - 1; i >= 0; i-- {
				arr[i] = vm.pop()
			}
			vm.push(arr)
		}

	case compiler.OpPop:
		vm.pop()

	case compiler.OpReturn:
		vm.retValue = vm.pop()
		vm.isRunning = false

	default:
		return pc + 1, fmt.Errorf("unknown opcode: %v", ins.Opcode)
	}

	return pc + 1, nil
}

// Helper methods

func (vm *VM) push(val interface{}) {
	vm.stack = append(vm.stack, val)
}

func (vm *VM) pop() interface{} {
	if len(vm.stack) == 0 {
		return nil
	}
	val := vm.stack[len(vm.stack)-1]
	vm.stack = vm.stack[:len(vm.stack)-1]
	return val
}

func (vm *VM) peek() interface{} {
	if len(vm.stack) == 0 {
		return nil
	}
	return vm.stack[len(vm.stack)-1]
}

func (vm *VM) add(left, right interface{}) interface{} {
	switch l := left.(type) {
	case float64:
		if r, ok := right.(float64); ok {
			return l + r
		}
	case string:
		if r, ok := right.(string); ok {
			return l + r
		}
	}
	return 0
}

func (vm *VM) subtract(left, right interface{}) interface{} {
	if l, ok := left.(float64); ok {
		if r, ok := right.(float64); ok {
			return l - r
		}
	}
	return 0
}

func (vm *VM) multiply(left, right interface{}) interface{} {
	if l, ok := left.(float64); ok {
		if r, ok := right.(float64); ok {
			return l * r
		}
	}
	return 0
}

func (vm *VM) divide(left, right interface{}) interface{} {
	if l, ok := left.(float64); ok {
		if r, ok := right.(float64); ok && r != 0 {
			return l / r
		}
	}
	return 0
}

func (vm *VM) modulo(left, right interface{}) interface{} {
	if l, ok := left.(float64); ok {
		if r, ok := right.(float64); ok && r != 0 {
			return float64(int64(l) % int64(r))
		}
	}
	return 0
}

func (vm *VM) equal(left, right interface{}) interface{} {
	switch l := left.(type) {
	case float64:
		if r, ok := right.(float64); ok {
			return l == r
		}
	case string:
		if r, ok := right.(string); ok {
			return l == r
		}
	case bool:
		if r, ok := right.(bool); ok {
			return l == r
		}
	case nil:
		return right == nil
	}
	return false
}

func (vm *VM) less(left, right interface{}) interface{} {
	if l, ok := left.(float64); ok {
		if r, ok := right.(float64); ok {
			return l < r
		}
	}
	return false
}

func (vm *VM) greater(left, right interface{}) interface{} {
	if l, ok := left.(float64); ok {
		if r, ok := right.(float64); ok {
			return l > r
		}
	}
	return false
}

func (vm *VM) isTruthy(val interface{}) bool {
	switch v := val.(type) {
	case bool:
		return v
	case nil:
		return false
	case float64:
		return v != 0
	case string:
		return v != ""
	default:
		return true
	}
}

func (vm *VM) toString(val interface{}) string {
	switch v := val.(type) {
	case nil:
		return "null"
	case bool:
		if v {
			return "true"
		}
		return "false"
	case float64:
		if v == float64(int64(v)) {
			return fmt.Sprintf("%d", int64(v))
		}
		return fmt.Sprintf("%f", v)
	case string:
		return v
	case []interface{}:
		return fmt.Sprintf("[array with %d elements]", len(v))
	default:
		return "[object]"
	}
}

func (vm *VM) getType(val interface{}) string {
	switch val.(type) {
	case nil:
		return "null"
	case bool:
		return "boolean"
	case float64:
		return "number"
	case string:
		return "string"
	case []interface{}:
		return "array"
	case map[string]interface{}:
		return "object"
	default:
		return "unknown"
	}
}

// ReturnValue returns the last return value
func (vm *VM) ReturnValue() interface{} {
	return vm.retValue
}

// Errors returns runtime errors
func (vm *VM) Errors() []RuntimeError {
	return vm.errors
}

