	summary := b.Summary()

	if !strings.Contains(summary, "✅") {
		t.Errorf("expected success indicator in summary, got '%s'", summary)
	}

	if !strings.Contains(summary, "5/5") {
		t.Errorf("expected '5/5 stages' in summary, got '%s'", summary)
	}
}

