	return fmt.Sprintf(`Profile: %s
  Duration: %.3f ms
  Allocated: %d bytes
  GC Runs: %d
  Stack Depth: %d
`,
		prof.Name,
		prof.Duration.Seconds()*1000,
		prof.AllocatedBytes,
		prof.GCRuns,
